{% set enc = {'0':'K','1':'M','2':'E','3':'R','4':'C','5':'H','6':'A','7':'N','8':'T','9':'S'} %}
{% for item in doc.items -%}
{# Fetch item details from Item Master #}
{% set item_doc = frappe.get_doc("Item", item.item_code) %}
{% set bc = (item.item_code or '')[:13] -%}
{% set nm = (item_doc.item_name or '')[:23] -%}

{# Fetch price from Price List #}
{% set price_list = doc.selling_price_list or doc.buying_price_list or "Standard Selling" %}
{% set price_data = frappe.get_all("Item Price", 
    filters={"item_code": item.item_code, "price_list": price_list}, 
    fields=["price_list_rate"], 
    limit=1) %}
{% set ra = '%.0f' % (price_data[0].price_list_rate | float if price_data else item.rate | float) -%}

{# Fetch valuation rate from Item Master or Stock Ledger #}
{% set rc = '%.0f' % (item_doc.valuation_rate | float if item_doc.valuation_rate else item.rate | float) -%}

{# Encode rates #}
{% set ns = namespace(rae='', rce='') %}
{% for d in ra %}{% set ns.rae = ns.rae + enc[d] %}{% endfor %}
{% for d in rc %}{% set ns.rce = ns.rce + enc[d] %}{% endfor %}

{% set qty = item.qty | int %}
{% set pairs = qty // 2 %}
{% set extra = qty % 2 %}

{# ----- print pairs (2 labels) ----- #}
{% for i in range(pairs) -%}
^XA
^PW612^LL200
^CI28
^FO10,5^A0N,25,25^FD{{ nm }}^FS
^FO10,30^BY2^BCN,55,N,N,N^FD{{ bc }}^FS
^FO25,95^A0N,25,25^FD{{ bc }}^FS
^FO25,120^A0N,25,25^FD{{ ns.rae }}^FS
^FO25,145^A0N,25,25^FD{{ ns.rce }}^FS
^FO315,5^A0N,25,25^FD{{ nm }}^FS
^FO315,30^BY2^BCN,55,N,N,N^FD{{ bc }}^FS
^FO335,95^A0N,25,25^FD{{ bc }}^FS
^FO335,120^A0N,25,25^FD{{ ns.rae }}^FS
^FO335,145^A0N,25,25^FD{{ ns.rce }}^FS
^XZ
{%- endfor %}

{# ----- print single label if odd qty ----- #}
{% if extra %}
^XA
^PW612^LL200
^CI28
^FO10,5^A0N,25,25^FD{{ nm }}^FS
^FO10,30^BY2^BCN,55,N,N,N^FD{{ bc }}^FS
^FO25,95^A0N,25,25^FD{{ bc }}^FS
^FO25,120^A0N,25,25^FD{{ ns.rae }}^FS
^FO25,145^A0N,25,25^FD{{ ns.rce }}^FS
^XZ
{% endif %}
{%- endfor %}

