{% set parts = document_name.split('||') %}
{% set party = parts[0] if parts|length > 0 else '' %}
{% set from_date = parts[1] if parts|length > 1 else '' %}
{% set to_date = parts[2] if parts|length > 2 else '' %}
{% set party_type = parts[3] if parts|length > 3 else 'Customer' %}

{% if party_type == 'Account' %}
  {% set entries = frappe.db.sql("""
      SELECT posting_date, voucher_type, voucher_no, debit, credit
      FROM `tabGL Entry`
      WHERE account = %(party)s
        AND posting_date BETWEEN %(from_date)s AND %(to_date)s
        AND is_cancelled = 0
      ORDER BY posting_date, creation
  """, {"party": party, "from_date": from_date, "to_date": to_date}, as_dict=True) %}
  {% set ob = frappe.db.sql("""
      SELECT COALESCE(SUM(debit),0) as d, COALESCE(SUM(credit),0) as c
      FROM `tabGL Entry`
      WHERE account = %(party)s AND posting_date < %(from_date)s AND is_cancelled = 0
  """, {"party": party, "from_date": from_date}, as_dict=True) %}
  {% set party_label = frappe.db.get_value('Account', party, 'account_name') or party %}
{% else %}
  {% set entries = frappe.db.sql("""
      SELECT posting_date, voucher_type, voucher_no, debit, credit
      FROM `tabGL Entry`
      WHERE party_type = %(party_type)s AND party = %(party)s
        AND posting_date BETWEEN %(from_date)s AND %(to_date)s
        AND is_cancelled = 0
      ORDER BY posting_date, creation
  """, {"party_type": party_type, "party": party, "from_date": from_date, "to_date": to_date}, as_dict=True) %}
  {% set ob = frappe.db.sql("""
      SELECT COALESCE(SUM(debit),0) as d, COALESCE(SUM(credit),0) as c
      FROM `tabGL Entry`
      WHERE party_type = %(party_type)s AND party = %(party)s
        AND posting_date < %(from_date)s AND is_cancelled = 0
  """, {"party_type": party_type, "party": party, "from_date": from_date}, as_dict=True) %}
  {% set name_field = party_type | lower + '_name' %}
  {% set party_label = frappe.db.get_value(party_type, party, name_field) or party %}
{% endif %}

{% set opening_balance = (ob[0].d or 0) - (ob[0].c or 0) %}

<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Arial, sans-serif; font-size: 11px; margin: 24px; color: #222; }
  h2 { margin: 0 0 2px; font-size: 15px; }
  .subtitle { color: #555; font-size: 10px; margin-bottom: 14px; }
  table { width: 100%; border-collapse: collapse; margin-top: 8px; }
  th { background: #e8edf2; text-align: left; padding: 6px 8px; border: 1px solid #b0bec5; font-size: 9px; text-transform: uppercase; letter-spacing: 0.5px; }
  td { padding: 5px 8px; border: 1px solid #dce3ea; }
  tr:nth-child(even) td { background: #f7f9fb; }
  .num { text-align: right; font-family: monospace; }
  .dr { color: #1b6b2e; font-weight: 600; }
  .cr { color: #b71c1c; font-weight: 600; }
  .dash { color: #bbb; }
  .ob-row td { background: #fffde7 !important; font-style: italic; }
  .total-row td { background: #e8edf2 !important; font-weight: bold; border-top: 2px solid #90a4ae; }
  .badge { font-size: 8px; font-weight: bold; padding: 1px 4px; border-radius: 3px; background: #dde8ff; color: #2c4db5; }
  .footer { margin-top: 14px; font-size: 9px; color: #999; }
</style>
</head>
<body>

<h2>{{ party_type }} Ledger &mdash; {{ party_label }}</h2>
<div class="subtitle">Party: {{ party }} &nbsp;&bull;&nbsp; Period: {{ from_date }} to {{ to_date }}</div>

<table>
  <thead>
    <tr>
      <th>Date</th>
      <th>Type</th>
      <th>Voucher No</th>
      <th class="num">Debit (Dr)</th>
      <th class="num">Credit (Cr)</th>
      <th class="num">Balance</th>
    </tr>
  </thead>
  <tbody>
    <tr class="ob-row">
      <td colspan="3">Opening Balance <span style="color:#aaa;font-size:9px">(before {{ from_date }})</span></td>
      <td class="num"></td>
      <td class="num"></td>
      <td class="num {{ 'dr' if opening_balance >= 0 else 'cr' }}">
        {{ '{:,.2f}'.format(opening_balance | abs) }} {{ 'Dr' if opening_balance >= 0 else 'Cr' }}
      </td>
    </tr>

    {% set ns = namespace(bal=opening_balance, tdr=0, tcr=0) %}
    {% for e in entries %}
      {% set ns.bal = ns.bal + (e.debit or 0) - (e.credit or 0) %}
      {% set ns.tdr = ns.tdr + (e.debit or 0) %}
      {% set ns.tcr = ns.tcr + (e.credit or 0) %}
      <tr>
        <td>{{ e.posting_date }}</td>
        <td><span class="badge">{{ e.voucher_type[:4] | upper }}</span></td>
        <td style="font-family:monospace;font-size:10px">{{ e.voucher_no }}</td>
        <td class="num">{% if e.debit %}<span class="dr">{{ '{:,.2f}'.format(e.debit) }}</span>{% else %}<span class="dash">&mdash;</span>{% endif %}</td>
        <td class="num">{% if e.credit %}<span class="cr">{{ '{:,.2f}'.format(e.credit) }}</span>{% else %}<span class="dash">&mdash;</span>{% endif %}</td>
        <td class="num {{ 'dr' if ns.bal >= 0 else 'cr' }}">{{ '{:,.2f}'.format(ns.bal | abs) }} {{ 'Dr' if ns.bal >= 0 else 'Cr' }}</td>
      </tr>
    {% endfor %}

    {% if entries %}
    <tr class="total-row">
      <td colspan="3">Closing Balance</td>
      <td class="num dr">{{ '{:,.2f}'.format(ns.tdr) }}</td>
      <td class="num cr">{{ '{:,.2f}'.format(ns.tcr) }}</td>
      <td class="num {{ 'dr' if ns.bal >= 0 else 'cr' }}">{{ '{:,.2f}'.format(ns.bal | abs) }} {{ 'Dr' if ns.bal >= 0 else 'Cr' }}</td>
    </tr>
    {% else %}
    <tr><td colspan="6" style="text-align:center;color:#999;padding:20px">No transactions found for the selected period.</td></tr>
    {% endif %}
  </tbody>
</table>

<div class="footer">Printed on {{ frappe.utils.now_datetime().strftime('%d/%m/%Y %H:%M') }}</div>
</body>
</html>

